from dataclasses import dataclass
from typing import List

@dataclass(frozen=True)
class OrderItem:
    sku: str
    quantity: int
    unit_cents: int

def compute_total_cents(items: List[OrderItem]) -> int:
    total = 0
    for item in items:
        if item.quantity < 0 or item.unit_cents < 0:
            raise ValueError('Negative quantity or price is not permitted')
        total += item.quantity * item.unit_cents
    return total

